// Find the "Meer om te vragen" block and the first web result
const paaBlock = element.closest('.ULSxyf') || element.closest('.MjjYud') || element.parentElement;
const firstResult = document.querySelector('.A6K0A[data-rpos="2"]');

if (!paaBlock || !firstResult) return;

// Find the MjjYud wrapper of the first result to insert after it
const firstResultContainer = firstResult.closest('.MjjYud') || firstResult.parentElement;
if (!firstResultContainer) return;

// Avoid re-inserting if already in position
if (paaBlock.previousElementSibling === firstResultContainer) return;

// Move the PAA block to appear directly after the first result container
firstResultContainer.parentNode.insertBefore(paaBlock, firstResultContainer.nextSibling);
